{"type":"begin","data":{"path":{"text":"arts.brown.edu/Secondary Navigation Navigation.txt"}}}
{"type":"match","data":{"path":{"text":"arts.brown.edu/Secondary Navigation Navigation.txt"},"lines":{"text":"Marti Noxon is a prolific writer/producer/director in both film and television. She's created and executive produced several high-profile television series including HBO's Emmy nominated Sharp Objects starring Amy Adams, critically acclaimed Dietland on AMC and Lifetime's UnReal, for which she received a Peabody award and an Emmy award nomination for Outstanding Writing in a Drama Series. Over the course of her impressive career, she has written and served as executive or consulting producer on numerous beloved series including Buffy the Vampire Slayer, Grey's Anatomy, Private Practice, Mad Men and Glee. Noxon is currently in development on Kill Show, for Apple TV, and Old Soul, for A24 television UK, among other projects. On the feature side, Noxon's directorial debut, To The Bone, premiered at Sundance and is one of the most streamed independent films on Netflix. Her additional film credits include Fight Night, I Am Number Four and the upcoming adaptation of Ronan Farrow's explosive expose of Harvey Weinstein, Catch And Kill.\n"},"line_number":49,"absolute_offset":3065,"submatches":[{"match":{"text":"consulting producer"},"start":477,"end":496}]}}
{"type":"end","data":{"path":{"text":"arts.brown.edu/Secondary Navigation Navigation.txt"},"binary_offset":null,"stats":{"elapsed":{"secs":0,"nanos":62637,"human":"0.000063s"},"searches":1,"searches_with_match":1,"bytes_searched":6468,"bytes_printed":1373,"matched_lines":1,"matches":1}}}
